import{_ as e,o as i,c as t,a2 as l}from"./chunks/framework.CHeM0PsO.js";const m=JSON.parse('{"title":"界面、主题与小工具","description":"","frontmatter":{},"headers":[],"relativePath":"guide/misskey/ui-themes.md","filePath":"guide/misskey/ui-themes.md","lastUpdated":1789295632000}'),s={name:"guide/misskey/ui-themes.md"};function r(o,a,n,d,u,c){return i(),t("div",null,[...a[0]||(a[0]=[l('<h1 id="界面、主题与小工具" tabindex="-1">界面、主题与小工具 <a class="header-anchor" href="#界面、主题与小工具" aria-label="Permalink to &quot;界面、主题与小工具&quot;">​</a></h1><h2 id="界面模式" tabindex="-1">界面模式 <a class="header-anchor" href="#界面模式" aria-label="Permalink to &quot;界面模式&quot;">​</a></h2><p>Misskey 提供两种整体界面布局，在侧栏菜单「切换界面」中选择：</p><ul><li><strong>默认界面</strong>：单列时间线 + 右侧信息栏，适合日常浏览。</li><li><strong>Deck</strong>：多栏布局，可把首页时间线、列表、天线、通知等多个「列」并排常驻，像专业客户端一样一屏监控多路信息。列可以自由添加、排列、调整宽度。</li></ul><p>手机等窄屏下会自动切换为移动端布局。</p><h2 id="主题" tabindex="-1">主题 <a class="header-anchor" href="#主题" aria-label="Permalink to &quot;主题&quot;">​</a></h2><ul><li>在「设置 → 主题」可以切换内置主题，本站默认为深色风格。</li><li>支持自定义主题：调整背景、强调色等，也可以从主题代码导入他人分享的主题。</li></ul><h2 id="小工具" tabindex="-1">小工具 <a class="header-anchor" href="#小工具" aria-label="Permalink to &quot;小工具&quot;">​</a></h2><p>时间线侧栏可以放置小工具（Widgets）：RSS 订阅、用户列表动态、状态栏等。</p><ul><li>点击界面上的小工具按钮进入编辑模式，拖拽添加、排列。</li><li>「状态栏」可以在页面顶部/底部常驻显示 RSS 等信息，在「设置 → 状态栏」配置。</li></ul><h2 id="声音与插件" tabindex="-1">声音与插件 <a class="header-anchor" href="#声音与插件" aria-label="Permalink to &quot;声音与插件&quot;">​</a></h2><ul><li>「设置 → 声音」：为通知、回应等事件设置提示音。</li><li>「设置 → 插件」：安装 AiScript 插件扩展客户端功能（如自定义发帖后操作）。</li><li>「设置 → 自定义 CSS」（高级）：注入自定义样式微调界面。</li></ul><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>自定义 CSS 和插件属于高级功能，安装来源不明的插件有风险，只添加可信的内容。</p></div>',13)])])}const p=e(s,[["render",r]]);export{m as __pageData,p as default};
